<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute } from 'vue-router'
import { api, apiPage, mutation, uploadAttachment } from '../api/client'
import RunPanel from '../components/RunPanel.vue'
type Goal={goal_version_id:string;role_direction:string}
type Evidence={kind:string;description:string;claimed_skills:string[];attachment_ids:string[];evidence_id:string;evidence_version_id:string;title:string;verification_scope:string;version:number}
type Criterion={dimension:'artifact'|'explanation'|'transfer';scenario:string;expected_behavior:string;pass_rule:string;fail_rule:string;unknown_rule:string;critical:boolean;allowed_methods:string[];required_artifact_types:string[];limitations:string[]}
type Objective={objective_id:string;objective_version_id:string;title:string;target_behavior:string;scope:string;origin:string;deliverables:string[];prerequisite_objective_ids:string[];effort_hours:{min:number;max:number}|null;criteria:Criterion[];criterion_version_ids:string[];version:number;goal_version_id:string}
type Plan={version_no?:number;plan_id:string;plan_version_id:string;version:number;kind:string;goal_version_id:string;active_plan_version_id:string|null;objective_version_ids:string[];objectives:Objective[];warnings?:string[]}
const goals=ref<Goal[]>([]), goalId=ref(''), evidence=ref<Evidence[]>([]), objectives=ref<Objective[]>([])
const reports=ref<{market_report_id:string;created_at:string}[]>([]), reportId=ref(''), evidenceIds=ref<string[]>([])
const plans=ref<Plan[]>([]), plan=ref<Plan|null>(null), selected=ref<string[]>([]), runId=ref(''), busy=ref(false)
const availableHours=ref<number|null>(null), evidenceFile=ref<File|null>(null), uploadedId=ref('')
const evidenceForm=reactive({kind:'readme',title:'',description:'',claimed_skills:''})
const write=mutation(), uploadKey=ref(crypto.randomUUID()), editingEvidence=ref<Evidence|null>(null)
const alignment=ref<{alignments:{category:string;reason:string;unknown_questions:string[]}[]}|null>(null)
const objectiveDialog=ref(false), editing=ref<Objective|null>(null)
const objectiveForm=reactive({title:'',target_behavior:'',scope:'',deliverables:'',prerequisite_objective_ids:[] as string[],estimate:false,min:1,max:4,criteria:[] as Criterion[],scope_confirmed:false})
function blankCriterion():Criterion{return {dimension:'artifact',scenario:'',expected_behavior:'',pass_rule:'',fail_rule:'观察不符合预期',unknown_rule:'材料或环境不完整',critical:true,allowed_methods:['human_review','user_reported'],required_artifact_types:['execution_record'],limitations:[]}}
async function all<T>(path:string):Promise<T[]>{const data:T[]=[];let cursor:string|null=null;do{const page:{data:T[];next_cursor?:string|null}=await apiPage<T>(path+(path.includes('?')?'&':'?')+'limit=100'+(cursor?'&cursor='+cursor:''));data.push(...page.data);cursor=page.next_cursor??null}while(cursor);return data}
async function load(){try{goals.value=await all<Goal>('/career-goals');if(!goalId.value)goalId.value=goals.value[0]?.goal_version_id??'';evidence.value=await all<Evidence>('/evidence');objectives.value=await all<Objective>('/learning-objectives');plans.value=await all<Plan>('/plans');await loadReports()}catch(e){ElMessage.error(String(e))}}
async function loadReports(){reports.value=await all('/market-reports?goal_version_id='+goalId.value);reportId.value=reports.value[0]?.market_report_id??''}
async function saveEvidence(){busy.value=true;try{if(evidenceFile.value&&!uploadedId.value){const result=await uploadAttachment(evidenceFile.value,'personal_evidence',uploadKey.value);uploadedId.value=result.attachment_id}
await write(editingEvidence.value?'/evidence/'+editingEvidence.value.evidence_id+'/versions':'/evidence','POST',{...(editingEvidence.value?{expected_version:editingEvidence.value.version,change_reason:'用户更新个人材料'}:{}),kind:evidenceForm.kind,title:evidenceForm.title,description:evidenceForm.description,claimed_skills:evidenceForm.claimed_skills.split(/[,，]/).map(x=>x.trim()).filter(Boolean),attachment_ids:uploadedId.value?[uploadedId.value]:(editingEvidence.value?.attachment_ids??[]),declared_verification:uploadedId.value?'attached_material':'self_reported',environment:{}});Object.assign(evidenceForm,{title:'',description:'',claimed_skills:''});evidenceFile.value=null;editingEvidence.value=null;uploadedId.value='';uploadKey.value=crypto.randomUUID();await load();ElMessage.success('已保存个人材料；未认定运行通过或能力掌握。')}catch(e){ElMessage.error(String(e))}finally{busy.value=false}}
function editEvidence(row:Evidence){editingEvidence.value=row;Object.assign(evidenceForm,{kind:row.kind,title:row.title,description:row.description,claimed_skills:row.claimed_skills.join(',')});uploadedId.value='';evidenceFile.value=null}
function cancelEvidence(){editingEvidence.value=null;Object.assign(evidenceForm,{kind:'readme',title:'',description:'',claimed_skills:''});uploadedId.value='';evidenceFile.value=null}
async function deleteEvidence(row:Evidence){try{await ElMessageBox.confirm('撤销后关联材料和历史衍生正文不可读取。确定删除这份个人材料？','删除个人材料',{type:'warning'});await write('/evidence/'+row.evidence_id,'DELETE',{expected_version:row.version});await load();ElMessage.success('材料读取已撤销。')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(String(e))}}
async function beginAlignment(){try{const run=await write<{run_id:string}>('/alignment-runs','POST',{goal_version_id:goalId.value,market_report_id:reportId.value,personal_evidence_version_ids:evidenceIds.value,user_constraints:{available_hours:availableHours.value}});runId.value=run.run_id}catch(e){ElMessage.error(String(e))}}
async function progress(){try{const run=await api<{output_refs:{plan_id?:string;alignment_report_id?:string}[]}>(`/runs/${runId.value}`);const result=run.output_refs.find(x=>x.plan_id);if(result?.alignment_report_id)alignment.value=await api('/alignment-reports/'+result.alignment_report_id);if(result?.plan_id){plan.value=await api<Plan>('/plans/'+result.plan_id);selected.value=[...plan.value.objective_version_ids];await load()}}catch(e){ElMessage.error(String(e))}}
function showPlan(row:Plan){plan.value=row;goalId.value=row.goal_version_id;selected.value=[...row.objective_version_ids]}
async function adopt(){if(!plan.value)return;try{const result=await write<{active_plan_version_id:string}>(`/plans/${plan.value.plan_id}/adopt`,'POST',{expected_version:plan.value.version,plan_version_id:plan.value.plan_version_id,expected_goal_version_id:plan.value.goal_version_id,selected_objective_version_ids:selected.value});plan.value=await api<Plan>(`/plans/${plan.value.plan_id}/versions/${result.active_plan_version_id}`);await load();ElMessage.success('已创建采纳版本，未创建实践任务。')}catch(e){ElMessage.error(String(e))}}
async function saveDraft(){if(!plan.value)return;try{plan.value=await write<Plan>(`/plans/${plan.value.plan_id}/versions`,'POST',{expected_version:plan.value.version,base_plan_version_id:plan.value.plan_version_id,objective_version_ids:selected.value,adjustment_reason:'用户调整目标与顺序',user_constraints:{available_hours:availableHours.value},deferred:[]});await load()}catch(e){ElMessage.error(String(e))}}
function openObjective(row:Objective|null){editing.value=row;Object.assign(objectiveForm,{title:row?.title??'',target_behavior:row?.target_behavior??'',scope:row?.scope??'',deliverables:row?.deliverables.join('\n')??'',prerequisite_objective_ids:row?.prerequisite_objective_ids??[],estimate:!!row?.effort_hours,min:row?.effort_hours?.min??1,max:row?.effort_hours?.max??4,criteria:row?(JSON.parse(JSON.stringify(row.criteria)) as Criterion[]).map(c=>({dimension:c.dimension,scenario:c.scenario,expected_behavior:c.expected_behavior,pass_rule:c.pass_rule,fail_rule:c.fail_rule,unknown_rule:c.unknown_rule,critical:c.critical,allowed_methods:c.allowed_methods,required_artifact_types:c.required_artifact_types,limitations:c.limitations})):[blankCriterion()],scope_confirmed:false});objectiveDialog.value=true}
async function saveObjective(){try{const body={goal_version_id:goalId.value,title:objectiveForm.title,target_behavior:objectiveForm.target_behavior,scope:objectiveForm.scope,deliverables:objectiveForm.deliverables.split('\n').filter(Boolean),prerequisite_objective_ids:objectiveForm.prerequisite_objective_ids,effort_hours:objectiveForm.estimate?{min:objectiveForm.min,max:objectiveForm.max,is_estimate:true}:null,criteria:objectiveForm.criteria,scope_confirmed:objectiveForm.scope_confirmed,...(editing.value?{expected_version:editing.value.version,change_reason:'用户核对并调整目标与条件'}:{})};await write(editing.value?`/learning-objectives/${editing.value.objective_id}/versions`:'/learning-objectives','POST',body);objectiveDialog.value=false;await load();ElMessage.success('目标与完整条件已保存为新版本。')}catch(e){ElMessage.error(String(e))}}
function move(index:number,delta:number){const next=index+delta;if(next<0||next>=selected.value.length)return;const a=selected.value[index]!,b=selected.value[next]!;selected.value[index]=b;selected.value[next]=a}
const route=useRoute()
onMounted(async()=>{await load();if(typeof route.query.plan==='string'){try{const saved=await api<Plan>('/plans/'+encodeURIComponent(route.query.plan));showPlan(saved);const hours=(saved as Plan & {user_constraints?:{available_hours:number|null}}).user_constraints?.available_hours;availableHours.value=hours??null}catch(e){ElMessage.error(String(e))}}})
</script>
<template>
<section class="page-heading"><div><span class="eyebrow">证据 → 目标 → 可采纳计划</span><h1>证据与学习计划</h1><p>缺材料保留未知。每个目标都有可检查的条件，采纳计划与创建任务分别进行。</p></div><el-button @click="load">刷新</el-button></section>
<el-alert title="离线规则模式；本人贡献、运行结果与理解深度需提供对应证据，不自动认证。" :closable="false"/>
<section class="table-card" style="padding:24px;margin:20px 0"><h2>个人材料</h2><el-form label-position="top"><el-form-item label="材料标题"><el-input v-model="evidenceForm.title" placeholder="例如 joblearn 的导入服务实现"/></el-form-item><el-form-item label="描述、本人贡献和未知范围"><el-input v-model="evidenceForm.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="自述关联技能（逗号分隔）"><el-input v-model="evidenceForm.claimed_skills"/></el-form-item><el-form-item label="文本附件（可选）"><input type="file" accept=".txt,.md,.json,.log,.py,.xml" @change="evidenceFile=($event.target as HTMLInputElement).files?.[0]??null;uploadedId=''"/></el-form-item><el-button type="primary" :loading="busy" @click="saveEvidence">{{editingEvidence?'保存材料新版本':'保存材料'}}</el-button><el-button v-if="editingEvidence" @click="cancelEvidence">取消编辑</el-button></el-form><el-table :data="evidence"><el-table-column prop="title" label="材料"/><el-table-column prop="verification_scope" label="证据来源"/><el-table-column prop="version" label="版本"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="editEvidence(row)">修改并保存新版本</el-button><el-button link type="danger" @click="deleteEvidence(row)">删除材料</el-button></template></el-table-column></el-table></section>
<section class="table-card" style="padding:24px;margin-bottom:20px"><h2>生成对齐草案</h2><el-form label-position="top"><el-form-item label="职业目标版本"><el-select v-model="goalId" @change="loadReports"><el-option v-for="g in goals" :key="g.goal_version_id" :label="g.role_direction" :value="g.goal_version_id"/></el-select></el-form-item><el-form-item label="岗位报告"><el-select v-model="reportId"><el-option v-for="r in reports" :key="r.market_report_id" :label="new Date(r.created_at).toLocaleString()" :value="r.market_report_id"/></el-select></el-form-item><el-form-item label="个人材料的具体版本"><el-select v-model="evidenceIds" multiple><el-option v-for="e in evidence" :key="e.evidence_version_id" :label="e.title+' · v'+e.version" :value="e.evidence_version_id"/></el-select></el-form-item><el-form-item label="本次可用总工时（可留空；不会替你假设时间）"><el-input-number v-model="availableHours" :min="1"/></el-form-item><el-button :disabled="!reportId" type="primary" @click="beginAlignment">生成离线草案</el-button><el-button @click="openObjective(null)">直接创建学习目标</el-button></el-form></section>
<RunPanel v-if="runId" :key="runId" :run-id="runId" @changed="progress"/>
<section v-if="alignment" class="table-card" style="padding:24px;margin:20px 0"><h2>证据对齐结果</h2><div v-for="(item,n) in alignment.alignments" :key="n"><strong>{{item.category==='unknown'?'未知':item.category}}</strong><p>{{item.reason}}</p><p v-for="q in item.unknown_questions" :key="q">补证问题：{{q}}</p></div></section><section class="table-card" style="padding:24px;margin:20px 0"><h2>学习目标</h2><el-table :data="objectives.filter(o=>o.goal_version_id===goalId)"><el-table-column prop="title" label="目标"/><el-table-column prop="origin" label="来源"/><el-table-column label="条件"><template #default="{row}">{{row.criteria.length}} 项</template></el-table-column><el-table-column label="核对"><template #default="{row}"><el-button link @click="openObjective(row)">查看与改版</el-button></template></el-table-column></el-table></section>
<section v-if="plans.length"><h2>计划版本</h2><el-button v-for="p in plans" :key="p.plan_id" @click="showPlan(p)">{{goals.find(g=>g.goal_version_id===p.goal_version_id)?.role_direction??'历史目标'}} · v{{p.version}} · {{p.kind==='draft'?'草稿':'已采纳'}}</el-button></section>
<section v-if="plan" class="table-card" style="padding:24px;margin-top:20px"><h2>{{plan.kind==='draft'?'计划草案':'采纳版本'}} · v{{plan.version_no??plan.version}}</h2><p>采纳前核对目标、条件和先修。时间未知时排期保持待定。</p><el-checkbox-group v-model="selected"><div v-for="o in plan.objectives" :key="o.objective_version_id"><el-checkbox :value="o.objective_version_id">{{o.title}}</el-checkbox><p>{{o.target_behavior}}</p><el-collapse><el-collapse-item title="查看完整验收条件"><p v-for="(c,n) in o.criteria" :key="n">{{c.dimension}} · {{c.expected_behavior}}；通过：{{c.pass_rule}}；未知：{{c.unknown_rule}}</p></el-collapse-item></el-collapse></div></el-checkbox-group><h3>选中目标的顺序</h3><div v-for="(id,n) in selected" :key="id">{{n+1}}. {{objectives.find(o=>o.objective_version_id===id)?.title??plan.objectives.find(o=>o.objective_version_id===id)?.title}} <el-button link @click="move(n,-1)">上移</el-button><el-button link @click="move(n,1)">下移</el-button></div><p><el-select v-model="selected" multiple placeholder="可加入已保存的同范围目标版本"><el-option v-for="o in objectives.filter(o=>o.goal_version_id===plan?.goal_version_id)" :key="o.objective_version_id" :label="o.title" :value="o.objective_version_id"/></el-select></p><el-button @click="saveDraft">保存新的编辑草稿</el-button><el-button type="primary" :disabled="plan.kind!=='draft'||!selected.length" @click="adopt">核对并采纳选中目标</el-button><p>采纳不会创建实践任务；下一步在“项目学习”选择参考实现，或在“自主构建”直接建立本人任务。</p></section>
<el-dialog v-model="objectiveDialog" title="目标与完整验收条件" width="min(860px,96vw)"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="objectiveForm.title"/></el-form-item><el-form-item label="要观察到的行为"><el-input v-model="objectiveForm.target_behavior" type="textarea"/></el-form-item><el-form-item label="范围和环境边界"><el-input v-model="objectiveForm.scope" type="textarea"/></el-form-item><el-form-item label="交付物（每行一项）"><el-input v-model="objectiveForm.deliverables" type="textarea"/></el-form-item><el-form-item label="先修目标"><el-select v-model="objectiveForm.prerequisite_objective_ids" multiple><el-option v-for="o in objectives.filter(o=>o.objective_id!==editing?.objective_id&&o.goal_version_id===goalId)" :key="o.objective_id" :label="o.title" :value="o.objective_id"/></el-select></el-form-item><el-checkbox v-model="objectiveForm.estimate">提供估计工时区间</el-checkbox><div v-if="objectiveForm.estimate"><el-input-number v-model="objectiveForm.min" :min="0"/> 至 <el-input-number v-model="objectiveForm.max" :min="1"/> 小时（估计）</div><div v-for="(c,n) in objectiveForm.criteria" :key="n" style="border-top:1px solid #ddd;margin-top:20px;padding-top:15px"><h3>条件 {{n+1}}</h3><el-select v-model="c.dimension"><el-option label="成果表现" value="artifact"/><el-option label="解释证据" value="explanation"/><el-option label="迁移证据" value="transfer"/></el-select><el-form-item label="场景"><el-input v-model="c.scenario"/></el-form-item><el-form-item label="可观察行为"><el-input v-model="c.expected_behavior"/></el-form-item><el-form-item label="通过规则"><el-input v-model="c.pass_rule"/></el-form-item><el-form-item label="失败规则"><el-input v-model="c.fail_rule"/></el-form-item><el-form-item label="未知规则"><el-input v-model="c.unknown_rule"/></el-form-item><el-form-item label="所需材料"><el-select v-model="c.required_artifact_types" multiple allow-create filterable><el-option v-for="a in ['execution_record','explanation_answer','transfer_note','code_artifact']" :key="a" :label="a" :value="a"/></el-select></el-form-item><el-form-item label="允许的检查方法"><el-checkbox-group v-model="c.allowed_methods"><el-checkbox value="model_review">材料辅助审阅</el-checkbox><el-checkbox value="user_reported">用户报告</el-checkbox><el-checkbox value="human_review">本人自验</el-checkbox></el-checkbox-group></el-form-item><el-checkbox v-model="c.critical">关键条件</el-checkbox><el-button link type="danger" @click="objectiveForm.criteria.splice(n,1)">移除此草案条件</el-button></div><el-button @click="objectiveForm.criteria.push(blankCriterion())">添加条件</el-button><p><el-checkbox v-model="objectiveForm.scope_confirmed">已核对本次范围、交付物和完整条件；改版不会修改旧任务。</el-checkbox></p></el-form><template #footer><el-button type="primary" :disabled="!objectiveForm.scope_confirmed" @click="saveObjective">保存目标版本</el-button></template></el-dialog>
</template>
